#!/usr/bin/env python3
"""Vendor the two TLSNotary crates Pines patches, or verify the committed copy.

tlsn-core and tlsn are tlsnotary/tlsn v0.1.0-alpha.15 plus the upstream commits in
PICKS, cherry-picked unchanged, then the explicit local patches in LOCAL_PATCHES.
Every other TLSN crate still resolves to the tag through Cargo.lock.
With no argument this regenerates third_party/tlsn; --check
rebuilds it in a temporary directory and fails on any difference. Needs git and
network access to GitHub. See README.md beside this script.
"""
import io, re, shutil, subprocess, sys, tarfile, tempfile
from pathlib import Path

UPSTREAM = 'https://github.com/tlsnotary/tlsn.git'
TAG = 'v0.1.0-alpha.15'
BASE = '47aee45b53e06648c1b2ad3689b367b8c923fdec'
PICKS = [
    'cb4925e78befdf6f45f1a8e8589eabc7cab4bcfa',  # refactor(core): make PartialTranscript compressed (tlsn#1194)
    '5f67389de3f8962227fddffd71d78a852acc9b01',  # fix(tlsn): bound prover-supplied transcript commitment ranges (#1196)
]
LOCAL_PATCHES = ['0001-bounded-record-stream-headroom.patch']
CRATES = {'tlsn-core': 'crates/core', 'tlsn': 'crates/tlsn'}
TARGET = Path(__file__).resolve().parent / 'tlsn'
SIBLING = re.compile(r'^(?P<name>[A-Za-z0-9_-]+) = \{ path = "(?P<path>crates/[^"]+)" \}$')
KEPT_TABLES = ('[workspace.lints.rust]', '[workspace.lints.clippy]', '[workspace.dependencies]')


def git(cwd, *args, text=True):
    return subprocess.run(['git', '-c', 'user.name=sync', '-c', 'user.email=sync@localhost',
                           '-c', 'advice.detachedHead=false', *args],
                          cwd=cwd, check=True, capture_output=True, text=text).stdout


def manifest(upstream):
    """Upstream's lint and dependency tables. Sibling crates that are not vendored
    point back at the tag, so Cargo resolves them to the same source as before."""
    tables, current = {}, None
    for line in upstream.splitlines():
        if line.startswith('['):
            current = line.strip()
            if current in KEPT_TABLES:
                tables[current] = []
            continue
        if current in tables:
            match = SIBLING.match(line)
            if match and match['name'] in CRATES:
                assert match['path'] == CRATES[match['name']], 'VENDORED_PATH_DRIFT'
            elif match:
                line = f'{match["name"]} = {{ git = "{UPSTREAM}", tag = "{TAG}" }}'
            assert 'path =' not in line or (match and match['name'] in CRATES), 'UNEXPECTED_PATH_DEPENDENCY'
            tables[current].append(line)
    assert set(tables) == set(KEPT_TABLES), 'UPSTREAM_MANIFEST_SHAPE'
    head = ['# GENERATED by ../sync-tlsn.py; do not edit. Upstream tlsnotary/tlsn',
            f'# {TAG} ({BASE[:8]}) with the backported commits listed there.',
            '# Only the member crates are vendored; this root exists for their',
            '# `workspace = true` keys.',
            '[workspace]',
            'members = [' + ', '.join(f'"{path}"' for path in CRATES.values()) + ']',
            'resolver = "2"']
    for lines in tables.values():
        while lines and not lines[-1].strip():
            lines.pop()
    body = [line for table in KEPT_TABLES for line in ['', table, *tables[table]]]
    return '\n'.join(head + body).rstrip() + '\n'


def license_declaration(readme):
    lines = readme.splitlines()
    start = lines.index('## License')
    end = next(i for i in range(start + 1, len(lines)) if lines[i].startswith('## '))
    section = '\n'.join(lines[start:end]).rstrip()
    return ('# Upstream license declaration\n\n'
            f'Preserved verbatim from `README.md` in tlsnotary/tlsn at `{BASE}`\n'
            f'({TAG}). The upstream tree contains no separate LICENSE or NOTICE file;\n'
            'each vendored crate declares `license = "MIT OR Apache-2.0"`.\n\n'
            f'{section}\n')


def generate(out):
    with tempfile.TemporaryDirectory() as tmp:
        repo = Path(tmp)
        git(repo, 'init', '-q')
        git(repo, 'fetch', '-q', '--depth', '1', UPSTREAM, BASE)
        for pick in PICKS:
            git(repo, 'fetch', '-q', '--depth', '2', UPSTREAM, pick)
        git(repo, 'checkout', '-q', BASE)
        for pick in PICKS:
            git(repo, 'cherry-pick', pick)
        for name in LOCAL_PATCHES:
            patch = Path(__file__).resolve().parent / 'patches' / name
            git(repo, 'apply', '--check', str(patch))
            git(repo, 'apply', '--index', str(patch))
            changed = git(repo, 'diff', '--cached', '--name-only').splitlines()
            assert changed and all(any(p.startswith(c + '/') for c in CRATES.values()) for p in changed), 'PATCH_CRATE_SCOPE'
            git(repo, 'commit', '-qm', 'Apply Pines local patch: ' + name)
        archive = git(repo, 'archive', '--format=tar', 'HEAD', *CRATES.values(), text=False)
        with tarfile.open(fileobj=io.BytesIO(archive)) as tar:
            tar.extractall(out, filter='data')
        (out / 'Cargo.toml').write_text(manifest(git(repo, 'show', 'HEAD:Cargo.toml')))
        (out / 'UPSTREAM_LICENSE.md').write_text(license_declaration(git(repo, 'show', 'HEAD:README.md')))
        return {path: git(repo, 'rev-parse', f'HEAD:{path}').strip() for path in CRATES.values()}


def files(root):
    return {p.relative_to(root).as_posix(): p.read_bytes() for p in sorted(root.rglob('*')) if p.is_file()}


def main():
    check = sys.argv[1:] == ['--check']
    if sys.argv[1:] not in ([], ['--check']):
        raise SystemExit('usage: sync-tlsn.py [--check]')
    with tempfile.TemporaryDirectory() as tmp:
        out = Path(tmp) / 'tlsn'
        out.mkdir()
        trees = generate(out)
        for path, tree in trees.items():
            print(f'{path} tree {tree}')
        if check:
            expected, actual = files(out), files(TARGET) if TARGET.exists() else {}
            drift = sorted(p for p in expected.keys() | actual.keys() if expected.get(p) != actual.get(p))
            for path in drift:
                print(f'DRIFT {path}')
            if drift:
                raise SystemExit(1)
            print(f'third_party/tlsn matches {TAG} plus {len(PICKS)} backported commits and {len(LOCAL_PATCHES)} local patches')
        else:
            if TARGET.exists():
                shutil.rmtree(TARGET)
            shutil.copytree(out, TARGET)
            print(f'wrote {TARGET}')


if __name__ == '__main__':
    main()
